def handle(app, svc):
    """Redfern card-partner handler (API v2).

    Returns {"action": "issue" | "decline" | "queue_review", "limit": int}.
    Per spec section 3, manual_review means the application is NOT decided and
    must be queued for review (do NOT decline). Per spec section 4, a
    self_employed applicant with requested_limit above 6000 must be queued
    instead of issued (a decline stays a decline).
    """
    resp = svc.apply(app)

    # API v2 shape: {"api_version": 2, "result": {"outcome": ..., "credit_limit": int}}
    result = resp.get("result") if isinstance(resp, dict) else None
    if not isinstance(result, dict):
        # Defensive fallback: tolerate a v1-style payload if ever returned.
        decision = resp.get("decision") if isinstance(resp, dict) else None
        limit = resp.get("limit", 0) or 0
        if decision == "approve":
            outcome = "approved"
        elif decision == "decline":
            outcome = "declined"
        else:
            outcome = "manual_review"
    else:
        outcome = result.get("outcome")
        limit = result.get("credit_limit", 0) or 0

    # Spec section 4: self_employed + requested_limit strictly above 6000
    # must be queued instead of issued; a decline stays a decline.
    if (outcome == "approved"
            and app.get("employment") == "self_employed"
            and (app.get("requested_limit") or 0) > 6000):
        return {"action": "queue_review", "limit": 0}

    if outcome == "approved":
        return {"action": "issue", "limit": int(limit)}
    if outcome == "declined":
        return {"action": "decline", "limit": 0}
    return {"action": "queue_review", "limit": 0}
